    old=json.loads((ROOT/'phase47-search-status.json').read_text(encoding='utf8'));s=dict(phase=48,status='terrain_rgb_bit_storage_and_scoped_projections_verified; unknown_gameplay_meanings_open',schema='terrain-lighting-semantics.json',validation='phase48-validation.json',findings=['Six RGB BYTE+flag channels, GUI0..511','Editor getters add256; game-loader WORD arithmetic adds255','Native decode/encode flag projection is lossy on unsupported or disabled-group channel bits; raw-preserving patch API separate','Actual Terrain GUI commit46E410 identified;46E350 is panel release'],unresolved=old['unresolved'],observed_input_drift=old['observed_input_drift'],input_manifest='phase47-input-manifest.json',next_action='Trace actual Terrain183/1B5 aliases or callbacks with verified Terrain object identity; lighting arithmetic does not identify198/224. Continue unresolved catalogue/creature consumers, preserve unknowns and historical snapshots.',scope='No research game-data writes; no full Terrain writer/UI/renderer execution.99 memory-only native cases. Original3EXEs unchanged.')
